<?php requireRole('student'); $s=$pdo->prepare('SELECT full_name,email,language,xp,level,streak,link_code FROM users WHERE id=?');$s->execute([userId()]);$u=$s->fetch(); ?>
<div class="card"><h1>👤 Profile</h1><p><strong>Name:</strong> <?=h($u['full_name'])?></p><p><strong>Email:</strong> <?=h($u['email'])?></p><p><strong>XP:</strong> <?=$u['xp']?></p><p><strong>Level:</strong> <?=$u['level']?></p><p><strong>Streak:</strong> <?=$u['streak']?></p><h2>Parent Link Code</h2><p>Give this code to your parent so they can track your progress:</p><div class="card"><strong style="font-size:28px;letter-spacing:4px"><?=h((string)$u['link_code'])?></strong></div></div>
